// Üretilen dosya: tool/ozgun/uret.py. Tarih · Millî Mücadele, Atatürk dönemi ve Cumhuriyet tarihi; 20. yüzyıl dünya tarihi (zor).
const ozHistory4Zor = <(String, String, List<String>, String)>[
  ('Erzurum Kongresi\'nin hangi kararı, Misak-ı Millî\'nin ve Lozan\'daki azınlık tartışmalarının temelini oluşturmuştur?', 'Azınlıklara siyasi ve sosyal dengeyi bozacak ayrıcalık verilmeyeceği', ['Kongrenin her yıl yeniden toplanacağı', 'Delegelerin padişaha bağlılık yemini edeceği ve onay alınacağı', 'Ordunun yeniden İstanbul\'a bağlanacağı'], 'Hristiyan azınlıklara siyasi egemenliği ve toplumsal dengeyi bozacak ayrıcalıklar tanınmayacağı kararı, sonraki millî belgelerde de korunmuştur.'),
  ('1919 yazında Mustafa Kemal\'e mektup yazarak Amerikan mandasının en az zararlı seçenek olduğunu savunan, Wilson Prensipleri Cemiyeti çevresinde yer alan yazar kimdir?', 'Halide Edib', ['Yakup Kadri Karaosmanoğlu', 'Falih Rıfkı Atay', 'Mehmet Âkif Ersoy'], 'Halide Edib, Wilson İlkeleri\'nden etkilenerek Amerikan mandasını savunmuş ve bu görüşünü Mustafa Kemal\'e mektupla iletmiştir. Manda fikri Sivas Kongresi\'nde reddedilmiştir.'),
  ('Amerika Birleşik Devletleri\'nin Anadolu\'ya gönderdiği ve Ermeni iddialarını yerinde inceleyen heyetin başkanı kimdir?', 'General Harbord', ['Amiral Calthorpe', 'General Franchet d\'Espèrey', 'Lord Curzon'], 'General James Harbord başkanlığındaki heyet 1919\'da Anadolu\'yu dolaşmış; raporunda Doğu Anadolu\'da Ermenilerin çoğunlukta olmadığını belirtmiştir.'),
  ('Misak-ı Millî\'de Boğazların güvenliği konusunda nasıl bir tutum benimsenmiştir?', 'İstanbul\'un güvenliği sağlanmak şartıyla ticarete açılabileceği', ['Boğazların sürekli olarak bütün yabancı gemilere kapatılacağı', 'Boğazların İngiltere yönetimine bırakılacağı', 'Boğazların Rusya ile ortak yönetileceği'], 'Misak-ı Millî, İstanbul ve Marmara\'nın güvenliği sağlanırsa Boğazların dünya ticaretine açılmasını ilgili devletlerle birlikte kararlaştırmayı kabul eder.'),
  ('TBMM açıldıktan sonra İstanbul\'da çıkarılan ve Kuvâ-yı Milliyecilerin öldürülmesinin dinen caiz olduğunu ileri süren fetvayı veren şeyhülislam kimdir?', 'Dürrizade Abdullah Efendi', ['Rıfat Börekçi', 'Mustafa Sabri Efendi', 'Ömer Hulusi Efendi'], 'Dürrizade Abdullah Efendi\'nin fetvasına karşı Ankara Müftüsü Rıfat Börekçi başta olmak üzere Anadolu müftüleri karşı fetva yayımlamıştır.'),
  ('Sevr Antlaşması\'na göre Osmanlı ordusunun en fazla kaç kişiden oluşması öngörülmüştü?', '50.700', ['100.000', '25.000', '80.500'], 'Sevr, Osmanlı ordusunu 50.700 kişiyle sınırlamış ve ağır silah bulundurmayı yasaklamıştır.'),
  ('Londra Konferansı\'nda TBMM heyetine başkanlık eden ve konferans sırasında İtilaf devletleriyle TBMM\'nin yetkisini aşan ikili antlaşmalar imzaladığı için eleştirilen kişi kimdir?', 'Bekir Sami Bey', ['İsmet Paşa', 'Yusuf Kemal Bey', 'Ali Fuat Paşa'], 'Dışişleri Bakanı Bekir Sami Bey, Londra\'da İngiltere, Fransa ve İtalya ile Misak-ı Millî\'ye aykırı ikili anlaşmalar imzalamış; TBMM bunları onaylamamış ve Bekir Sami istifa etmiştir.'),
  ('Sakarya zaferinin diplomatik sonuçları arasında aşağıdakilerden hangisi yer almaz?', 'Mudanya Ateşkesi\'nin imzalanması', ['Kars Antlaşması\'nın imzalanması', 'Fransa ile Ankara Antlaşması\'nın imzalanması', 'İtalyanların Anadolu\'dan çekilmeyi hızlandırması'], 'Sakarya\'nın ardından Ekim 1921\'de Kars ve Ankara antlaşmaları imzalanmış, İtalya çekilmiştir. Mudanya ise Büyük Taarruz\'dan sonra, Ekim 1922\'de imzalanmıştır.'),
  ('Fransa ile imzalanan 1921 Ankara Antlaşması\'nda Hatay (İskenderun Sancağı) için öngörülen düzenleme nedir?', 'Özel bir yönetim kurulması ve Türk kültürünün korunması', ['Hemen ve doğrudan Türkiye\'ye katılması', 'İngiltere\'ye bırakılması', 'Ermenistan\'a verilmesi'], 'Ankara Antlaşması ile Hatay Fransız mandası altındaki Suriye sınırları içinde kalmış, ancak özel bir yönetim ve Türkçenin resmî dil olması kabul edilmiştir.'),
  ('İzmir\'in kurtuluşunun ardından Türk ordusunun Boğazlara yönelmesi karşısında İngiltere\'nin barış yolunu seçmesinde aşağıdakilerden hangisi etkili olmuştur?', 'Fransa ve İtalya\'nın İngiltere\'yi desteklememesi', ['Yunanistan\'ın İngiltere\'ye savaş açması', 'ABD\'nin Türkiye\'ye asker göndermesi', 'Rusya\'nın Boğazları ve İstanbul\'u işgal etmesi'], 'Çanakkale Krizi sırasında Fransa ve İtalya, İngiltere\'nin Türklere karşı yeni bir savaşına katılmayı reddetmiş; yalnız kalan İngiltere ateşkese razı olmuştur.'),
  ('Mudanya Ateşkesi\'nin ardından Doğu Trakya\'yı teslim almak üzere görevlendirilen TBMM temsilcisi kimdir?', 'Refet Bele', ['Kâzım Özalp', 'Ali Fuat Cebesoy', 'Fahrettin Altay'], 'Refet Paşa, Ekim 1922\'de İstanbul\'a gelerek TBMM adına Doğu Trakya\'yı teslim alma işlerini yürütmüştür.'),
  ('Lozan\'da Türk ve Yunan halklarının karşılıklı olarak yer değiştirmesini öngören sözleşmenin dışında tutulan iki topluluk hangisidir?', 'İstanbul Rumları ile Batı Trakya Türkleri', ['İzmir Rumları ile Girit Türkleri', 'Trabzon Rumları ile Selanik ve Kavala Türkleri', 'Kıbrıs Rumları ile Rodos Türkleri'], '30 Ocak 1923\'te imzalanan mübadele sözleşmesi, İstanbul\'da yerleşik Rumlar ile Batı Trakya\'daki Türkleri kapsam dışında bırakmıştır.'),
  ('Halifeliğin kaldırılmasını hazırlayan gelişmelerden biri, Hindistanlı Müslüman liderlerin İsmet Paşa\'ya yazdığı mektubun bazı İstanbul gazetelerinde yayımlanmasıdır. Bu mektupta ne istenmişti?', 'Halifenin yetkilerinin artırılması ve saygınlığının korunması', ['Halifenin Hindistan\'a taşınması', 'Halifeliğin İngiltere\'ye devredilmesi', 'Halifeliğin hemen ve tamamen kaldırılması'], 'Ağa Han ve Emir Ali\'nin mektubu, halifenin konumunun güçlendirilmesini istiyordu; mektubun yayımlanması yabancıların iç işlere karıştığı tartışmasını büyüterek halifeliğin kaldırılmasını hızlandırmıştır.'),
  ('1921 Teşkilât-ı Esasiye Kanunu, Kanun-ı Esasi\'yi tümüyle yürürlükten kaldırmamıştır. Bu durum nasıl yorumlanabilir?', 'İki anayasanın bir süre birlikte yürürlükte kaldığı', ['Osmanlı padişahının yetkilerinin yeniden genişletildiği', 'Cumhuriyetin önceden ilan edildiği', 'Kanun-ı Esasi\'nin 1921\'de yeniden yazıldığı'], '1921 Anayasası kısa ve olağanüstü dönem anayasasıydı; kendisiyle çelişmeyen Kanun-ı Esasi maddeleri yürürlükte kalmış, bu ikilik 1924 Anayasası ile sona ermiştir.'),
  ('1921 Anayasası\'nda yer alan "vilayetlere geniş yetki verilmesi" ilkesi hangi yönetim anlayışını yansıtır?', 'Yerinden yönetim', ['Merkeziyetçi yönetim', 'Federal sistem', 'Monarşik yönetim'], '1921 Anayasası illere ve nahiyelere şûralar aracılığıyla geniş yetkiler tanıyarak yerinden yönetimi (adem-i merkeziyet) öngörmüştür.'),
  ('1924 Teşkilât-ı Esasiye Kanunu\'na "Devletin dini, din-i İslam\'dır" maddesinin çıkarılması ve laiklik ilkesinin eklenmesi hangi yıllarda gerçekleşmiştir?', '1928 ve 1937', ['1924 ve 1930', '1926 ve 1934', '1925 ve 1938'], 'Devletin dini maddesi 1928\'de anayasadan çıkarılmış, laiklik ilkesi ise diğer Atatürk ilkeleriyle birlikte 1937\'de anayasaya girmiştir.'),
  ('Terakkiperver Cumhuriyet Fırkası\'nın programındaki "dinî inançlara saygılıdır" ifadesi kapatılma sürecinde neden önem kazanmıştır?', 'Rejim karşıtlarının partiyi kendilerine sığınak görmesine zemin hazırladığı için', ['Partinin laikliği anayasaya ekleme önerisi olarak görüldüğü ve tepki çektiği için', 'Halifeliğin kaldırılmasını savunduğunun kanıtı sayıldığı için', 'Partinin devletçilik ilkesini benimsediğini gösterdiği için'], 'Bu ifade, inkılaplara karşı olan çevrelerce istismar edilmiş; Şeyh Said İsyanı\'ndan sonra parti, isyancıları cesaretlendirdiği gerekçesiyle 1925\'te kapatılmıştır.'),
  ('Çok partili hayata geçiş denemelerinin 1925 ve 1930\'da başarısız olması aşağıdakilerden hangisini göstermektedir?', 'Muhalefetin rejim karşıtlarınca istismar edilmesinin demokratik gelişimi geciktirdiğini', ['Türkiye\'de hiçbir zaman çok partili seçim yapılmadığını', 'Atatürk\'ün muhalefete her koşulda ve her dönemde karşı olduğunu ve hiçbir partiye izin vermediğini', 'Lozan Antlaşması\'nın parti kurmayı yasakladığını'], 'Her iki denemede de muhalefet partileri inkılap karşıtlarının toplandığı yer hâline gelmiş; bu durum çok partili hayata kalıcı geçişi 1946\'ya kadar ertelemiştir.'),
  ('1926 tarihli Türk Ceza Kanunu ile Ticaret Kanunu sırasıyla hangi ülkelerin kanunlarından yararlanılarak hazırlanmıştır?', 'İtalya ve Almanya', ['Fransa ve İsviçre', 'Almanya ve Fransa', 'İsviçre ve İtalya'], 'Ceza Kanunu İtalya\'dan, Ticaret Kanunu Almanya\'dan uyarlanmıştır. Borçlar Kanunu ise İsviçre\'den alınmıştır.'),
  ('Ezanın Türkçe okunmasını zorunlu kılan uygulama hangi yıl başlamış ve hangi yıl kaldırılmıştır?', '1932\'de başlamış, 1950\'de kaldırılmıştır', ['1924\'te başlamış, 1938\'de kaldırılmıştır', '1928\'de başlamış, 1946\'da kaldırılmıştır', '1934 yılında başlamış, 1960 yılında kaldırılmıştır'], 'Türkçe ezan uygulaması 1932\'de başlamış; Demokrat Parti iktidarı 1950\'de Arapça ezan yasağını kaldırmıştır.'),
  ('1935 genel seçimleri ve hemen ardından yapılan ara seçim sonucunda TBMM\'deki kadın milletvekili sayısı kaça ulaşmıştır?', '18', ['4', '9', '31'], '1935 seçimlerinde 17 kadın milletvekili seçilmiş, kısa süre sonra yapılan ara seçimle bu sayı 18\'e çıkmıştır. Bu, 1934\'te tanınan siyasi hakların ilk uygulamasıdır.'),
  ('1950\'de Mersin belediye başkanlığına seçilerek Türkiye\'nin ilk kadın belediye başkanı olan kişi kimdir?', 'Müfide İlhan', ['Gül Esin', 'Sabiha Sertel', 'Nezihe Muhiddin'], 'Müfide İlhan 1950\'de Mersin\'de seçilerek ilk kadın belediye başkanı olmuştur. Gül Esin ise 1933\'te Aydın\'da seçilen ilk kadın muhtardır.'),
  ('Birinci Beş Yıllık Sanayi Planı (1934-1938) döneminde kurulan fabrikalardan biri aşağıdakilerden hangisidir?', 'Kayseri Bez Fabrikası', ['Seydişehir Alüminyum Tesisleri', 'Ereğli Demir-Çelik Fabrikası', 'Bursa Otomobil Fabrikası'], 'Kayseri Bez Fabrikası 1935\'te Birinci Beş Yıllık Sanayi Planı kapsamında açılmıştır. Ereğli Demir-Çelik 1960\'larda, Seydişehir Alüminyum 1970\'lerde, Bursa\'daki otomobil fabrikaları ise 1960\'ların sonundan itibaren kurulmuştur.'),
  ('Musul sorununda Milletler Cemiyeti\'nin İngiltere lehine karar vermesi Türkiye\'nin hangi dönemde bu örgüte katılımını nasıl etkilemiştir?', 'Türkiye\'nin örgüte şüpheyle yaklaşmasına ve üyeliğin 1932\'ye kalmasına yol açmıştır', ['Türkiye\'nin hemen 1926\'da örgüte katılmasını ve Konsey\'e girmesini sağlamıştır', 'Türkiye\'nin örgütten çıkarılmasına neden olmuştur', 'Türkiye\'nin örgütün kurucu üyesi olmasına yol açmıştır'], 'Musul kararı Milletler Cemiyeti\'nin büyük devletlerin etkisinde olduğu izlenimini güçlendirmiş; Türkiye ancak 1932\'de, davet üzerine üye olmuştur.'),
  ('Türkiye\'nin Lozan\'da eksik kalan Boğazlar meselesini 1936\'da yeniden gündeme getirebilmesinde hangi uluslararası gelişme etkili olmuştur?', 'Almanya ve İtalya\'nın saldırgan politikalarıyla silahsızlanma sisteminin çökmesi', ['ABD\'nin Milletler Cemiyeti\'ne üye olması ve Avrupa\'ya doğrudan askerî müdahalede bulunması', 'Sovyetler Birliği\'nin dağılması ve Karadeniz\'in serbest kalması', 'İngiltere\'nin Boğazlardan doğrudan pay istemesi'], 'İtalya\'nın Habeşistan\'ı işgali ve Almanya\'nın Ren bölgesini silahlandırması gibi gelişmeler, Türkiye\'nin güvenlik gerekçesiyle Lozan\'daki düzenlemeyi değiştirme talebini haklı kılmıştır.'),
  ('Mustafa Kemal\'in 1905\'te ilk görev yeri olarak gönderildiği ve burada Vatan ve Hürriyet Cemiyeti\'ni kurduğu şehir hangisidir?', 'Şam', ['Selanik', 'Trablus', 'Sofya'], 'Mustafa Kemal ilk görevi için Şam\'daki 5. Ordu\'ya gönderilmiş ve burada arkadaşlarıyla Vatan ve Hürriyet Cemiyeti\'ni kurmuştur.'),
  ('Mustafa Kemal\'in 1913\'te askerî ataşe olarak görev yaptığı şehir hangisidir?', 'Sofya', ['Berlin', 'Paris', 'Atina'], 'Mustafa Kemal Balkan Savaşları\'ndan sonra Sofya\'ya askerî ataşe olarak atanmış ve 1915\'e kadar bu görevi sürdürmüştür.'),
  ('1961 Anayasası\'yla kurulan Millî Güvenlik Kurulu\'nun varlığı hangi açıdan eleştirilmiştir?', 'Askerlerin siyasete etkisini kurumsallaştırdığı için', ['Yalnızca sivillerden oluştuğu için', 'Kuruluşundan bu yana hiçbir toplantı yapmadığı için', 'Meclisin yerine yasama yaptığı için'], 'Millî Güvenlik Kurulu, komutanların hükümetle birlikte güvenlik politikalarını belirlediği bir organ olarak askerin siyasal alandaki etkisini kalıcı hâle getirmiştir.'),
  ('1982 Anayasası\'nın 1961 Anayasası\'na göre temel farkı aşağıdakilerden hangisidir?', 'Yürütmeyi güçlendirip hak ve özgürlüklere daha fazla sınırlama getirmesi', ['İki meclisli yapıyı sürdürmesi ve Cumhuriyet Senatosu\'nu güçlendirmesi', 'Anayasa Mahkemesi\'ni ilk kez kurması', 'Cumhurbaşkanının yetkilerini tümüyle kaldırması'], '1982 Anayasası tek meclisli yapıya dönmüş, cumhurbaşkanının yetkilerini artırmış ve hak ile özgürlükler için geniş sınırlama nedenleri öngörmüştür.'),
  ('1969\'da Fas\'ın Rabat kentinde kurulan ve Türkiye\'nin de üyesi olduğu uluslararası örgüt hangisidir?', 'İslam Konferansı Örgütü', ['Arap Birliği', 'Ekonomik İşbirliği Teşkilatı', 'Bağlantısızlar Hareketi'], 'İslam Konferansı Örgütü (bugün İslam İşbirliği Teşkilatı), Mescid-i Aksa\'nın kundaklanması sonrası 1969\'da Rabat\'ta kurulmuştur.'),
  ('I. Dünya Savaşı sonunda Avusturya ile imzalanan antlaşma hangisidir?', 'Saint-Germain', ['Trianon', 'Neuilly', 'Sevr'], 'Avusturya ile Saint-Germain (1919), Macaristan ile Trianon (1920), Bulgaristan ile Neuilly (1919) ve Osmanlı ile Sevr (1920) imzalanmıştır.'),
  ('II. Dünya Savaşı sonrası kurulan Uluslararası Para Fonu (IMF) ve Dünya Bankası\'nın temelini atan 1944 konferansı hangisidir?', 'Bretton Woods', ['Potsdam', 'Yalta', 'Tahran'], 'Temmuz 1944\'te ABD\'nin Bretton Woods kasabasında yapılan konferansta IMF ile Dünya Bankası\'nın kurulması ve doların altına bağlı sabit kur sistemi kararlaştırılmıştır.'),
  ('Fransa\'nın Çinhindi\'ndeki egemenliğinin sona ermesine yol açan 1954 yenilgisi hangisidir?', 'Dien Bien Phu', ['Saygon', 'Hue', 'Hanoi'], 'Viet Minh güçlerinin 1954\'te Dien Bien Phu\'da Fransızları yenmesinin ardından Cenevre Konferansı\'nda Vietnam 17. paralelden ikiye ayrılmıştır.'),
  ('1961\'de ABD destekli Kübalı sürgünlerin Castro\'yu devirmek için düzenlediği başarısız çıkarma hangisidir?', 'Domuzlar Körfezi Çıkarması', ['Guantanamo Körfezi Harekâtı', 'Grenada Müdahalesi', 'Panama Harekâtı'], 'Nisan 1961\'deki Domuzlar Körfezi Çıkarması başarısız olmuş ve Küba\'nın Sovyetlere daha da yakınlaşmasına yol açmıştır.'),
  ('Gana\'yı 1957\'de bağımsızlığa kavuşturan ve Sahra altı Afrika\'da bağımsızlığını kazanan ilk sömürgelerden birinin lideri olan kişi kimdir?', 'Kwame Nkrumah', ['Jomo Kenyatta', 'Patrice Lumumba', 'Léopold Senghor'], 'Kwame Nkrumah önderliğinde Altın Kıyısı adıyla bilinen İngiliz sömürgesi 1957\'de Gana adıyla bağımsız olmuştur. Kenyatta Kenya\'nın, Lumumba Kongo\'nun, Senghor Senegal\'in lideridir.'),
  ('Süveyş Krizi\'nin uluslararası ilişkilerdeki en önemli sonucu aşağıdakilerden hangisidir?', 'İngiltere ve Fransa\'nın büyük güç konumunun sarsılması', ['ABD\'nin Orta Doğu\'dan tümüyle çekilmesi', 'Mısır\'ın kanal üzerindeki haklarını kaybetmesi', 'İsrail\'in Sina\'yı kalıcı olarak ilhak etmesi'], 'ABD ve SSCB\'nin ortak baskısıyla geri çekilmek zorunda kalan İngiltere ve Fransa\'nın eski sömürgeci güçlerini kaybettikleri açıkça görülmüştür.'),
  ('Çin\'in 1971\'de BM\'deki Güvenlik Konseyi koltuğunu Tayvan\'dan devralması neyi gösterir?', 'Uluslararası alanın Çin Halk Cumhuriyeti\'ni meşru Çin hükümeti olarak tanımasını', ['Tayvan\'ın BM\'nin daimi üyesi olarak kalmasını', 'Çin\'in BM\'den çekilmesini', 'Sovyetler Birliği\'nin Çin\'i ilhak etmesini'], 'BM Genel Kurulu\'nun 2758 sayılı kararıyla Çin\'in temsil hakkı Pekin hükümetine geçmiş ve Tayvan örgüt dışında kalmıştır.'),
  ('1972\'de ABD Başkanı Nixon\'ın Çin\'i ziyaret etmesi Soğuk Savaş dengeleri açısından nasıl yorumlanır?', 'ABD\'nin Çin-Sovyet ayrılığını kullanarak SSCB\'yi dengelemeye çalışması', ['Çin\'in Varşova Paktı\'na katılması', 'ABD\'nin Tayvan\'ı Çin\'e satması', 'Çin\'in kapitalist sisteme hemen geçmesi'], '1960\'larda Çin ile SSCB arasında derin bir ayrılık oluşmuştu; Nixon\'ın ziyareti bu ayrılıktan yararlanarak Sovyetlere karşı denge kurma stratejisidir.'),
  ('Avrupa Ekonomik Topluluğu\'na 1973\'te katılan ülkeler arasında aşağıdakilerden hangisi yer alır?', 'Birleşik Krallık', ['İspanya', 'Yunanistan', 'Avusturya'], '1973\'teki ilk genişlemede Birleşik Krallık, İrlanda ve Danimarka topluluğa katılmıştır. Yunanistan 1981\'de, İspanya 1986\'da, Avusturya 1995\'te katılmıştır.'),
  ('Fransa Cumhurbaşkanı Charles de Gaulle\'ün 1960\'larda İngiltere\'nin topluluğa katılmasını iki kez veto etmesinin temel gerekçesi neydi?', 'İngiltere\'nin ABD\'ye fazla yakın olduğunu düşünmesi', ['İngiltere\'nin Varşova Paktı üyesi olması', 'İngiltere\'nin kömür üretmemesi', 'İngiltere\'nin Akdeniz\'de toprağı bulunmaması ve uzak olması'], 'De Gaulle, İngiltere\'nin ABD ile özel ilişkisinin Avrupa\'nın bağımsızlığını zayıflatacağını düşünmüş; İngiltere ancak onun ardından 1973\'te katılabilmiştir.'),
  ('Türkiye\'nin 1991\'de Sovyetler\'den ayrılan Türk cumhuriyetleri arasında bağımsızlığını ilk tanıdığı ülke hangisidir?', 'Azerbaycan', ['Kazakistan', 'Özbekistan', 'Türkmenistan'], 'Türkiye 9 Kasım 1991\'de Azerbaycan\'ın bağımsızlığını tanıyan ilk ülke olmuş; diğer Türk cumhuriyetlerini Aralık 1991\'de tanımıştır.'),
  ('Soğuk Savaş döneminde ABD ile SSCB arasındaki silahlanma yarışının nükleer savaşa dönüşmemesi genellikle hangi kavramla açıklanır?', 'Karşılıklı kesin yok oluş', ['Güç ayrılığı ilkesi', 'Kolektif güvenlik sistemi ile Milletler Cemiyeti\'nin etkinliği', 'Serbest ticaret anlayışı'], 'Her iki tarafın da karşı tarafı yok edebilecek nükleer kapasiteye sahip olması, ilk saldırıyı intihar anlamına getirmiş ve doğrudan savaşı caydırmıştır.'),
  ('ABD Başkanı Ronald Reagan\'ın 1983\'te açıkladığı ve uzay tabanlı füze savunma sistemi öngören program hangi adla anılır?', 'Stratejik Savunma Girişimi', ['Manhattan Projesi', 'Apollo Programı', 'Atom Barış İçin Programı'], '"Yıldız Savaşları" olarak da bilinen Stratejik Savunma Girişimi, Sovyet füzelerini uzayda imha etmeyi hedeflemiş ve silahlanma yarışını yeniden hızlandırmıştır.'),
  ('Büyük Taarruz\'un ardından İzmir\'e 9 Eylül 1922\'de ilk giren Türk süvari birliklerinin komutanı kimdir?', 'Fahrettin Altay', ['Kâzım Karabekir', 'Ali Fuat Cebesoy', 'Refet Bele'], 'Fahrettin Altay komutasındaki 5. Süvari Kolordusu\'na bağlı birlikler 9 Eylül 1922\'de İzmir\'e girmiştir.'),
  ('Büyük Taarruz sırasında Türk ordusuna esir düşen Yunan başkomutanı kimdir?', 'General Trikupis', ['General Papulas', 'Kral Konstantin', 'Venizelos'], 'Yunan ordusunun başkomutanı General Nikolaos Trikupis, 2 Eylül 1922\'de Uşak yakınlarında esir alınmıştır.'),
  ('Damat Ferit hükümeti Sivas Kongresi\'nin toplanmasını engellemek için hangi girişimde bulunmuştur?', 'Elazığ valisi Ali Galip\'i kongreyi dağıtmakla görevlendirmek', ['Kongre üyelerine milletvekilliği teklif etmek', 'Sivas\'ı İngilizlere teslim etmek', 'Kongreyi İstanbul\'a taşımak için seçim yapmak'], 'Ali Galip olayı ortaya çıkınca Temsil Heyeti İstanbul ile bütün bağlantıları kesmiş ve bu süreç Damat Ferit hükümetinin düşmesine yol açmıştır.'),
  ('Mondros Ateşkesi\'nden sonra Antep, Maraş ve Urfa başlangıçta hangi devlet tarafından işgal edilmiş, sonra hangi devlete bırakılmıştır?', 'İngiltere işgal etmiş, Fransa\'ya bırakmıştır', ['Fransa işgal etmiş, İtalya\'ya bırakmıştır', 'İtalya işgal etmiş, Yunanistan\'a bırakmıştır', 'Yunanistan işgal etmiş, İngiltere\'ye bırakmıştır'], 'Bu şehirler önce İngilizlerce işgal edilmiş, 1919\'da İngiliz-Fransız anlaşmasıyla Fransızlara devredilmiştir.'),
  ('Sakarya Savaşı öncesinde Başkomutan Mustafa Kemal\'in, ordunun ihtiyaçlarını karşılamak için halktan malzeme toplanmasını sağlayan emirleri hangi adla anılır?', 'Tekâlif-i Milliye Emirleri', ['İstiklal Mahkemeleri', 'Teşkilat-ı Mahsusa', 'Müdafaa-i Hukuk Cemiyetleri'], 'Ağustos 1921\'de yayımlanan Tekâlif-i Milliye Emirleri ile halkın elindeki yiyecek, giyecek, taşıt ve silahların bir kısmı orduya verilmiş; uygulama ilçelere kadar kurulan komisyonlarca yürütülmüştür.'),
  ('Lozan Antlaşması\'nda Türkiye-Suriye sınırının belirlenmesinde hangi antlaşma esas alınmıştır?', '1921 Ankara Antlaşması', ['Moskova Antlaşması', 'Sevr Antlaşması', 'Gümrü Antlaşması'], 'Lozan\'da güney sınırı için Fransa ile 1921\'de imzalanan Ankara Antlaşması\'ndaki sınır kabul edilmiştir.'),
  ('Cumhuriyetin ilanı ile ilgili kanun teklifi 29 Ekim 1923\'te TBMM\'de kabul edilirken hangi anayasada değişiklik yapılmıştır?', '1921 Teşkilât-ı Esasiye Kanunu', ['1924 Teşkilât-ı Esasiye Kanunu', 'Kanun-ı Esasi', '1961 Anayasası'], 'Cumhuriyet, 1921 Anayasası\'nın bazı maddelerinin değiştirilmesiyle ilan edilmiş; "Türkiye Devleti\'nin şekl-i hükümeti Cumhuriyettir" maddesi eklenmiştir.'),
  ('Atatürk döneminde Ankara\'da kurulan ve hukukçu yetiştirmeyi amaçlayan ilk yükseköğretim kurumu hangisidir?', 'Ankara Hukuk Mektebi', ['Mekteb-i Mülkiye', 'Dil ve Tarih-Coğrafya Fakültesi', 'Yüksek Ziraat Enstitüsü'], 'Ankara Hukuk Mektebi 5 Kasım 1925\'te açılmış; hukuk inkılabını uygulayacak hukukçuların yetiştirilmesi amaçlanmıştır.'),
  ('Türk Dil Kurumu\'nun ilk adı aşağıdakilerden hangisidir?', 'Türk Dili Tetkik Cemiyeti', ['Türk Ocakları Dil Encümeni', 'Türk Tarihi Tetkik Cemiyeti', 'Encümen-i Daniş'], 'Türk Dil Kurumu 12 Temmuz 1932\'de Türk Dili Tetkik Cemiyeti adıyla kurulmuştur. Türk Tarih Kurumu\'nun ilk adı ise Türk Tarihi Tetkik Cemiyeti\'dir.'),
  ('Atatürk döneminde nüfus mübadelesi sonucunda Türkiye\'ye gelen göçmenlerin yerleşmesi için hangi kurum kurulmuştur?', 'Mübadele, İmar ve İskân Vekâleti', ['Diyanet İşleri Başkanlığı', 'Vakıflar Genel Müdürlüğü', 'Kızılay Cemiyeti Genel Merkezi'], '1923\'te kurulan Mübadele, İmar ve İskân Vekâleti, Yunanistan\'dan gelen göçmenlerin iskânı ve mübadele işleriyle görevlendirilmiştir.'),
  ('Türkiye ile Sovyetler Birliği arasında 1925\'te imzalanan Dostluk ve Tarafsızlık Antlaşması hangi gelişmenin hemen ardından imzalanmıştır?', 'Milletler Cemiyeti\'nin Musul kararının', ['Montrö Sözleşmesi\'nin imzalanmasının', 'Hatay\'ın Türkiye\'ye katılmasının', 'Balkan Antantı\'nın kurulmasının'], 'Aralık 1925\'te Milletler Cemiyeti Musul\'u Irak\'a bırakan kararı verince, Türkiye birkaç gün sonra Sovyetlerle dostluk antlaşması imzalayarak Batı\'ya karşı denge arayışına girmiştir.'),
  ('Atatürk\'ün Balkan Antantı\'nın kurulmasındaki rolüne karşılık, 1934\'te Nobel Barış Ödülü\'ne aday gösterilmesini öneren devlet adamı kimdir?', 'Elefterios Venizelos', ['Josip Broz Tito', 'Benito Mussolini', 'Aristide Briand'], 'Yunan devlet adamı Venizelos, Türk-Yunan dostluğuna ve Balkan barışına katkıları nedeniyle Atatürk\'ü 1934\'te Nobel Barış Ödülü\'ne aday göstermiştir.'),
  ('Türkiye\'nin İkinci Dünya Savaşı öncesinde 1939\'da İngiltere ve Fransa ile imzaladığı antlaşma hangisidir?', 'Üçlü İttifak Antlaşması', ['Sadabad Paktı', 'Bağdat Paktı', 'Montrö Sözleşmesi'], '19 Ekim 1939\'da imzalanan Türk-İngiliz-Fransız Üçlü İttifakı, Akdeniz\'de saldırıya uğrandığında yardımlaşmayı öngörmüştür.'),
  ('1943\'te Türkiye\'nin savaşa girmesi için baskı yapıldığı, İnönü ile Churchill\'in görüştüğü toplantı hangisidir?', 'Adana Görüşmesi', ['Yalta Konferansı', 'Potsdam Konferansı', 'Kazablanka Konferansı ve Tahran Görüşmesi'], 'Ocak 1943\'te Adana\'da yapılan görüşmede Churchill Türkiye\'yi savaşa sokmaya çalışmış, İnönü ise ordunun yetersiz donanımını gerekçe göstererek savaşa girmemiştir.'),
  ('DP iktidarının son yıllarında muhalefeti ve basını soruşturmak için Meclis\'te kurulan ve 1960 müdahalesine giden gerginliği artıran komisyon hangisidir?', 'Tahkikat Komisyonu', ['Millî Birlik Komitesi', 'Danışma Meclisi', 'Kurucu Meclis'], 'Nisan 1960\'ta kurulan Tahkikat Komisyonu\'na olağanüstü yetkiler verilmesi büyük tepki doğurmuş, öğrenci olayları ve ardından 27 Mayıs müdahalesi gelmiştir.'),
  ('1961 Anayasası\'nı hazırlayan ve Temsilciler Meclisi ile Millî Birlik Komitesi\'nden oluşan yapı hangi adla anılır?', 'Kurucu Meclis', ['Danışma Meclisi', 'Millî Güvenlik Konseyi', 'Cumhuriyet Senatosu'], '1961 Anayasası, Millî Birlik Komitesi ile Temsilciler Meclisi\'nden oluşan Kurucu Meclis tarafından hazırlanmış ve halkoylamasıyla kabul edilmiştir.'),
  ('1963\'te Kıbrıs\'ta Rumların Türklere yönelik saldırılarına verilen ad ve ardından ABD Başkanı Johnson\'ın Türkiye\'ye gönderdiği uyarı mektubu birlikte düşünüldüğünde hangisi doğrudur?', 'Kanlı Noel olayları; Johnson Mektubu Türkiye\'nin adaya müdahalesini engellemiştir', ['Barış Harekâtı; Johnson Mektubu Türkiye\'ye askerî destek sağlamıştır', 'Enosis Bildirisi; Johnson Mektubu adayı Yunanistan\'a vermiştir', 'Zürih Antlaşması; Johnson Mektubu NATO\'dan çıkışı istemiştir'], 'Aralık 1963 Kanlı Noel saldırıları üzerine Türkiye müdahaleye hazırlanmış; 1964 Johnson Mektubu bunu engelleyerek Türk-Amerikan ilişkilerini sarsmış ve Türkiye\'yi çok yönlü dış politikaya yöneltmiştir.'),
  ('Truman Doktrini ile Marshall Planı arasındaki temel fark aşağıdakilerden hangisidir?', 'Truman Doktrini Türkiye ile Yunanistan\'a yönelik, Marshall Planı ise Avrupa geneline yöneliktir', ['Truman Doktrini ekonomik, Marshall Planı yalnız askerî yardımdır', 'Truman Doktrini Sovyetlere, Marshall Planı Çin\'e yardımdır', 'İkisi de yalnızca Japonya\'ya yöneliktir'], '1947 Truman Doktrini Türkiye ve Yunanistan\'a askerî ve ekonomik yardımı, Marshall Planı ise Batı Avrupa\'nın geniş çaplı ekonomik kalkınmasını hedeflemiştir.'),
  ('Sovyetlerin 1968\'de Çekoslovakya\'ya müdahalesini meşrulaştırmak için öne sürdüğü, sosyalist bir ülkedeki tehdidin bütün blokun sorunu olduğunu savunan anlayış hangisidir?', 'Brejnev Doktrini', ['Truman Doktrini', 'Eisenhower Doktrini', 'Nixon Doktrini'], 'Brejnev Doktrini, Varşova Paktı ülkelerinin egemenliğinin sosyalist blokun çıkarlarıyla sınırlı olduğunu ileri sürmüştür; Gorbaçov döneminde terk edilmiştir.'),
  ('Türkiye\'ye Avrupa Birliği\'ne aday ülke statüsünün tanındığı zirve hangisidir?', '1999 Helsinki Zirvesi', ['1997 Lüksemburg Zirvesi', '1992 Maastricht Zirvesi', '1975 Helsinki Konferansı'], 'Aralık 1999 Helsinki Zirvesi\'nde Türkiye resmen aday ülke olarak kabul edilmiştir. 1997 Lüksemburg Zirvesi\'nde ise Türkiye aday listesine alınmamıştı.'),
  ('Türkiye, İran ve Pakistan\'ın 1964\'te kurduğu Kalkınma İçin Bölgesel İşbirliği (RCD) daha sonra hangi örgüte dönüşmüştür?', 'Ekonomik İşbirliği Teşkilatı', ['CENTO', 'İslam İşbirliği Teşkilatı', 'Şanghay İşbirliği Örgütü'], 'RCD, 1985\'te Ekonomik İşbirliği Teşkilatı adını almış ve 1992\'de Orta Asya cumhuriyetleri ile Afganistan\'ın katılımıyla genişlemiştir.'),
  ('Türkiye 1961\'de hangi ekonomik örgütün kurucu üyeleri arasında yer almıştır?', 'Ekonomik İşbirliği ve Kalkınma Örgütü', ['Avrupa Ekonomik Topluluğu', 'OPEC', 'Dünya Ticaret Örgütü ve GATT'], 'Türkiye, Marshall yardımlarını dağıtmak için kurulan OEEC\'nin 1948\'den üyesiydi; OEEC 1961\'de OECD\'ye dönüşünce Türkiye kurucu üyeler arasında yer almıştır.'),
  ('Mustafa Kemal\'in Çanakkale Savaşı\'ndaki başarılarıyla ilgili olarak Anafartalar Grup Komutanlığı\'na getirilmesi hangi gelişmenin ardından olmuştur?', 'İtilaf kuvvetlerinin Ağustos 1915\'te Suvla\'ya çıkarma yapması', ['Mondros Ateşkesi\'nin imzalanması', 'Gelibolu\'nun tamamen boşaltılması', 'Kut\'ül-Amare\'nin düşmesi ve İngilizlerin esir alınması'], 'İtilaf kuvvetlerinin Ağustos 1915\'te Suvla Koyu\'na çıkması üzerine Mustafa Kemal Anafartalar Grup Komutanı olmuş ve Anafartalar ile Conkbayırı zaferlerini kazanmıştır.'),
  ('1958-1961 yılları arasında Mısır ile Suriye\'nin birleşmesiyle oluşan devlet hangisidir?', 'Birleşik Arap Cumhuriyeti', ['Arap Ligi', 'Bereketli Hilal Federasyonu', 'Arap Federasyonu ve Haşimi Krallığı'], 'Mısır ile Suriye 1958\'de Birleşik Arap Cumhuriyeti adıyla birleşmiş, Suriye 1961\'deki darbeyle birlikten ayrılmıştır.'),
  ('İran\'da 1951\'de petrolü millîleştiren ve 1953\'te ABD ile İngiltere destekli darbeyle devrilen başbakan kimdir?', 'Muhammed Musaddık', ['Ayetullah Humeyni', 'Ali Ekber Haşimi Rafsancani', 'Muhammed Hatemi'], 'Musaddık\'ın Anglo-İranian Petrol Şirketi\'ni millîleştirmesinin ardından 1953\'te düzenlenen darbeyle Şah\'ın yetkileri yeniden güçlendirilmiştir.'),
  ('1962\'de bağımsızlığını kazanan Cezayir\'de bağımsızlık mücadelesini yürüten örgüt hangisidir?', 'Ulusal Kurtuluş Cephesi', ['Afrika Ulusal Kongresi', 'Filistin Kurtuluş Örgütü', 'Viet Minh ve Çinhindi Komünist Partisi'], 'FLN 1954\'te silahlı mücadeleyi başlatmış ve Evian Antlaşmaları\'nın ardından Cezayir 1962\'de bağımsız olmuştur. Afrika Ulusal Kongresi Güney Afrika\'nın örgütüdür.'),
  ('Belçika sömürgesiyken 1960\'ta bağımsızlığını kazanan ve ilk başbakanı Patrice Lumumba olan ülke hangisidir?', 'Kongo', ['Gana', 'Kenya', 'Nijerya'], 'Kongo 30 Haziran 1960\'ta Belçika\'dan bağımsız olmuş, Lumumba kısa süre sonra devrilip 1961\'de öldürülmüştür.'),
  ('Sömürgecilikten kurtuluş sürecinde Asya\'da bağımsızlığını ilk kazanan ülkelerden biri olan Filipinler hangi devletin yönetimindeydi?', 'Amerika Birleşik Devletleri', ['İspanya', 'Hollanda', 'Fransa'], 'Filipinler 1898\'den sonra ABD yönetimine geçmiş ve 4 Temmuz 1946\'da bağımsızlığını kazanmıştır. Daha önce İspanyol sömürgesiydi.'),
  ('II. Dünya Savaşı\'ndan sonra sömürgeciliğin hızla çözülmesinde aşağıdakilerden hangisinin etkisi en azdır?', 'Milletler Cemiyeti\'nin manda sistemini güçlendirmesi', ['Avrupa devletlerinin savaşta zayıflaması', 'BM\'nin self-determinasyon ilkesini benimsemesi', 'Sömürgelerde ulusal bilincin gelişmesi'], 'Avrupa\'nın zayıflaması, BM Şartı\'ndaki halkların kendi kaderini tayin hakkı ve yerel milliyetçi hareketler sömürgecilikten kurtuluşu hızlandırmıştır. Milletler Cemiyeti ise 1946\'da dağılmıştı.'),
  ('1975\'te 35 ülkenin imzaladığı ve Avrupa\'da sınırların dokunulmazlığı ile insan haklarına saygıyı öngören belge hangisidir?', 'Helsinki Nihai Senedi', ['Paris Şartı', 'Atlantik Bildirisi', 'Roma Antlaşması'], 'Avrupa Güvenlik ve İşbirliği Konferansı sonunda imzalanan Helsinki Nihai Senedi yumuşama döneminin doruk noktası sayılır; Türkiye de imzacılar arasındadır.'),
  ('1987\'de Reagan ile Gorbaçov arasında imzalanan ve bir nükleer füze sınıfını tamamen ortadan kaldıran antlaşma hangisidir?', 'Orta Menzilli Nükleer Kuvvetler (INF) Antlaşması', ['SALT I Antlaşması', 'Nükleer Silahların Yayılmasını Önleme Antlaşması', 'Kısmi Test Yasağı Antlaşması'], 'INF Antlaşması orta menzilli karadan atılan nükleer füzelerin tümüyle yok edilmesini öngörmüş ve Soğuk Savaş\'ın sona ermesine giden süreçte önemli bir adım olmuştur.'),
  ('1991\'de Yugoslavya\'dan ilk bağımsızlığını ilan eden iki cumhuriyet hangileridir?', 'Slovenya ve Hırvatistan', ['Bosna-Hersek ve Makedonya', 'Sırbistan ve Karadağ', 'Kosova ve Bosna-Hersek'], 'Slovenya ve Hırvatistan 25 Haziran 1991\'de bağımsızlık ilan etmiştir; Makedonya aynı yıl, Bosna-Hersek ise 1992\'de onları izlemiştir.'),
  ('Kurtuluş Savaşı\'nda Batı Cephesi\'nin ilk komutanı olarak görev yapan ve sonra Moskova büyükelçisi olan komutan kimdir?', 'Ali Fuat Cebesoy', ['İsmet İnönü', 'Fevzi Çakmak', 'Kâzım Karabekir ve Doğu Cephesi Komutanlığı'], 'Ali Fuat Paşa Batı Cephesi komutanıyken Kasım 1920\'de Moskova büyükelçiliğine atanmış, cephe İsmet ve Refet beyler arasında ikiye ayrılmıştır.'),
  ('I. TBMM\'de Mustafa Kemal\'i destekleyenlerin oluşturduğu grup ile ona muhalif olanların grubu sırasıyla hangi adlarla anılır?', 'Birinci Grup ve İkinci Grup', ['Halk Fırkası ve Terakkiperver Fırka', 'İttihatçılar ve İtilafçılar', 'Müdafaa-i Hukuk ve Hürriyet ve İtilaf'], '1921\'de Mustafa Kemal\'in önderliğinde Anadolu ve Rumeli Müdafaa-i Hukuk Grubu (Birinci Grup) kurulmuş; muhalifler İkinci Grup adıyla örgütlenmiştir.'),
  ('Mustafa Kemal\'in TBMM açılmadan önce Heyet-i Temsiliye adına yaptığı ve İstanbul\'daki mebuslara verdiği görev, Misak-ı Millî\'yi meclise kabul ettirecek bir grup kurmaktı. Bu grubun adı nedir?', 'Felah-ı Vatan Grubu', ['Birinci Grup', 'Müdafaa-i Hukuk Grubu', 'İkinci Grup'], 'Son Osmanlı Mebusan Meclisi\'nde Misak-ı Millî\'yi savunmak üzere kurulan Felah-ı Vatan Grubu, Mustafa Kemal\'in başkan seçilmesi isteğini gerçekleştirememiş ancak Misak-ı Millî\'nin kabulünü sağlamıştır.'),
  ('Mustafa Kemal\'in Son Osmanlı Mebusan Meclisi\'nde başkan seçilmesini istemesinin amacı neydi?', 'Heyet-i Temsiliye\'nin varlığını ve millî iradenin denetimini meclis aracılığıyla sürdürmek', ['Padişahın tahttan indirilmesini sağlamak', 'Meclisi Ankara\'da toplamak', 'Sevr\'i onaylatmak ve barışı sağlamak'], 'Mustafa Kemal, meclis başkanı olarak Heyet-i Temsiliye\'nin varlığını sürdürmeyi ve millî iradeyi koruma altına almayı amaçlamıştır; ancak bu gerçekleşmemiştir.'),
  ('1920 sonunda Gediz Baskını\'nın başarısız olması hangi sonucu doğurmuştur?', 'Düzenli ordu kurulması gerektiğinin anlaşılması', ['Yunan ordusunun İzmir\'e geri çekilmesi', 'Sevr Antlaşması\'nın feshedilmesi', 'Mudanya Ateşkesi\'nin imzalanması'], 'Ekim 1920\'deki Gediz Baskını\'nda Kuvâ-yı Milliye ve düzenli birliklerin başarısız olması, dağınık yapının yetersizliğini göstermiş ve düzenli orduya geçişi hızlandırmıştır.'),
  ('1928\'de kabul edilen bir düzenlemeyle Arap rakamları yerine hangi rakamlar kullanılmaya başlanmıştır?', 'Uluslararası (Batı) rakamları', ['Roma rakamları', 'Ebced hesabındaki harf değerleri', 'Fenike rakamları'], '1928\'de Arap rakamları yerine uluslararası rakamlar kabul edilmiş; aynı yıl Harf İnkılabı da gerçekleşmiştir.'),
  ('1930\'ların sonunda Türkiye\'de kurulan ve bugün Türkiye\'nin en köklü sanayi kuruluşlarından sayılan Karabük Demir Çelik Fabrikaları hangi yıl üretime başlamıştır?', '1939', ['1927', '1945', '1950'], 'Karabük Demir Çelik Fabrikaları İkinci Beş Yıllık Sanayi Planı çerçevesinde 1937\'de temeli atılarak 1939\'da üretime geçmiştir.'),
  ('Türkiye\'de radyo yayıncılığı ilk kez hangi şehirde ve hangi yıl başlamıştır?', 'İstanbul, 1927', ['Ankara, 1923', 'İzmir, 1935', 'Ankara, 1938'], 'Türkiye\'de ilk radyo yayını 6 Mayıs 1927\'de İstanbul\'da başlamış, Ankara Radyosu ise 1938\'de yayına geçmiştir.'),
  ('Francisco Franco\'nun İspanya İç Savaşı\'nı kazanmasının ardından İspanya\'nın II. Dünya Savaşı\'ndaki tutumu ne olmuştur?', 'Resmen savaşa girmemiştir', ['Müttefiklerin yanında savaşmıştır', 'Sovyetlerle ittifak kurmuştur', 'Almanya\'ya savaş ilan edip Fransa\'yı kurtarmıştır'], 'Franco, Mihver Devletleri\'ne sempati duymasına rağmen İspanya\'yı savaşa sokmamış; yalnızca Doğu Cephesi\'ne "Mavi Tümen" adlı gönüllü birlik göndermiştir.'),
  ('II. Dünya Savaşı\'nda Japonya\'nın teslim olma belgesini imzaladığı yer neresidir?', 'Tokyo Körfezi\'nde USS Missouri zırhlısı', ['Hiroşima Belediye Binası', 'Pearl Harbor deniz üssündeki karargâh', 'Pekin\'deki Yasak Şehir'], 'Japonya 2 Eylül 1945\'te Tokyo Körfezi\'ndeki USS Missouri zırhlısında teslim belgesini imzalamış ve II. Dünya Savaşı resmen sona ermiştir.'),
  ('Avrupa\'nın birleşmesi fikrinin öncülerinden olan ve 1950\'de kömür ile çeliğin ortak yönetimini öneren Fransız dışişleri bakanı kimdir?', 'Robert Schuman', ['Jean Monnet', 'Charles de Gaulle', 'François Mitterrand'], '9 Mayıs 1950\'deki Schuman Bildirisi Avrupa Kömür ve Çelik Topluluğu\'nun temelini atmıştır; bu gün Avrupa Günü olarak kutlanır. Jean Monnet planın mimarı sayılır.'),
  ('1968\'de imzaya açılan ve nükleer silahların yayılmasını önlemeyi amaçlayan antlaşma hangisidir?', 'Nükleer Silahların Yayılmasını Önleme Antlaşması', ['SALT II Antlaşması', 'INF Antlaşması', 'Moskova Kısmi Test Yasağı Antlaşması'], '1968\'de imzaya açılan ve 1970\'te yürürlüğe giren antlaşma, nükleer silahı olmayan ülkelerin bu silahları edinmemesini ve nükleer güçlerin silahsızlanmasını öngörür.'),
  ('Bir öğrenci Millî Mücadele\'de imzalanan antlaşmaları imza tarihine göre sıralamak istiyor. Doğru sıralama hangisidir?', 'Gümrü, Moskova, Ankara, Mudanya', ['Moskova, Gümrü, Mudanya, Ankara', 'Ankara, Gümrü, Moskova, Mudanya', 'Gümrü, Ankara, Mudanya, Moskova'], 'Gümrü 3 Aralık 1920, Moskova 16 Mart 1921, Ankara 20 Ekim 1921, Mudanya 11 Ekim 1922\'de imzalanmıştır.'),
  ('Moskova Antlaşması\'nda Batum\'un Gürcistan\'a bırakılması ile Lozan\'da Batı Trakya\'nın Yunanistan\'da kalması arasındaki ortak nokta nedir?', 'Her ikisi de Misak-ı Millî\'den verilmiş tavizlerdir', ['Her ikisi de halk oylamasıyla belirlenmiştir', 'Her ikisinde de bölgeler Türkiye\'ye katılmıştır', 'Her ikisi de Mudanya Ateşkesi görüşmelerinde kararlaştırılmıştır'], 'Misak-ı Millî\'de Elviye-i Selase ve Batı Trakya için halk oylaması öngörülmüştü; ancak Batum Moskova\'da, Batı Trakya Lozan\'da Türkiye dışında kalmıştır.'),
  ('Terakkiperver Cumhuriyet Fırkası ile Serbest Cumhuriyet Fırkası karşılaştırıldığında aşağıdakilerden hangisi yalnızca Serbest Cumhuriyet Fırkası için doğrudur?', 'Atatürk\'ün isteğiyle kurulmuş olması', ['Kısa sürede kapanmış olması', 'İnkılap karşıtlarınca istismar edilmesi', 'Liberal bir ekonomi anlayışını savunması'], 'SCF Atatürk\'ün isteğiyle kurulmuştur; TpCF ise Atatürk\'e muhalif paşalarca kurulmuştur. Her iki parti de kısa ömürlü olmuş, istismar edilmiş ve liberal görüşler savunmuştur.'),
  ('Türkiye\'nin 1946-1952 arasında Batı ile bütünleşme sürecindeki adımlar aşağıdakilerin hangisinde doğru sırayla verilmiştir?', 'Truman Doktrini, Marshall Planı, Avrupa Konseyi, NATO', ['NATO, Truman Doktrini, Avrupa Konseyi, Marshall Planı', 'Marshall Planı, NATO, Truman Doktrini, Avrupa Konseyi', 'Avrupa Konseyi, NATO, Marshall Planı, Truman Doktrini'], 'Truman Doktrini Mart 1947, Marshall Planı 1948\'de Türkiye\'yi kapsamış, Avrupa Konseyi üyeliği 1949, NATO üyeliği ise 1952\'dir.'),
  ('1960, 1971 ve 1980 müdahaleleri karşılaştırıldığında 1971\'i diğerlerinden ayıran özellik nedir?', 'Meclisin kapatılmadan bir muhtırayla hükümetin istifaya zorlanması', ['Yeni bir anayasanın hazırlanması', 'Bütün siyasi partilerin kapatılması', 'Yönetimin doğrudan askerî bir kurula geçmesi ve meclisin dağıtılması'], '12 Mart 1971\'de meclis açık kalmış, muhtırayla hükümet değişmiştir. 1960 ve 1980\'de ise yönetim askerî kurullara geçmiş ve yeni anayasalar yapılmıştır.'),
  ('Sovyetler Birliği\'nin dağılmasında aşağıdakilerden hangisinin etkisi en azdır?', 'Marshall Planı\'nın Doğu Avrupa\'ya uygulanması', ['Ekonomik durgunluk ve silahlanma yarışının maliyeti', 'Glasnost ve perestroyka reformları', 'Cumhuriyetlerdeki milliyetçi hareketler'], 'Marshall Planı yalnız Batı Avrupa\'ya uygulanmış, Sovyetler ve Doğu bloku bu planı reddetmiştir. Diğerleri dağılmanın temel nedenleri arasındadır.'),
  ('Bir öğretmen tahtaya şu üç maddeyi yazıyor: "Kuvâ-yı Milliye\'yi âmil, irade-i milliyeyi hâkim kılmak esastır", "Manda ve himaye kabul olunamaz", "Bütün cemiyetler tek ad altında birleşmiştir." Bu maddelerin ortak kaynağı hangisidir?', 'Sivas Kongresi kararları', ['Havza Genelgesi', 'Amasya Genelgesi', 'Mudanya Ateşkes Antlaşması'], 'Cemiyetlerin Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti adı altında birleştirilmesi Sivas Kongresi\'nde gerçekleştiği için maddelerin ortak kaynağı Sivas Kongresi\'dir; diğer iki madde de bu kongrede yeniden kabul edilmiştir.'),
  ('Lozan\'da Türkiye\'nin kapitülasyonlar konusunda hiç taviz vermemesine karşın Musul konusunda görüşmeyi erteleme yolunu seçmesi nasıl değerlendirilebilir?', 'Bağımsızlığı öncelemek için toprak sorununu sonraya bırakan gerçekçi bir tutum', ['Musul\'u kesin olarak İngiltere\'ye bırakan bir teslimiyet', 'Kapitülasyonları İngiltere\'ye karşı pazarlık aracı olarak kullanma', 'Konferansı bozmaya yönelik bilinçli bir girişim'], 'Türk heyeti tam bağımsızlığın temeli olan kapitülasyonlarda uzlaşmamış, Musul\'u ise barışı tehlikeye atmamak için ikili görüşmelere bırakmıştır.'),
  ('Halifeliğin kaldırılmasından sonra bazı İslam ülkelerinde halife seçme girişimleri sonuçsuz kalmıştır. Bu durum aşağıdaki çıkarımlardan hangisini destekler?', 'Halifeliğin siyasi bir kurum olarak etkinliğini yitirdiğini', ['Halifeliğin Türkiye\'de yeniden kurulduğunu', 'Bütün İslam ülkelerinin tek devlette birleştiğini', 'Halifeliğin İngiltere\'ye devredildiğini'], '1924\'ten sonra Kahire ve Mekke\'de toplanan kongreler yeni bir halife üzerinde uzlaşamamış; bu, kurumun siyasi işlevini kaybettiğini göstermiştir.'),
  ('1924 Anayasası\'nın uzun süre yürürlükte kalmasının nedeni olarak aşağıdakilerden hangisi gösterilebilir?', 'Gerektiğinde değişikliklerle yeni düzenlemelere uyum sağlayabilmesi', ['Hiçbir maddesinin değiştirilmemesi', 'Halkoylamasıyla kabul edilmiş olması', 'Yalnızca savaş dönemine yönelik olması'], '1924 Anayasası 1928, 1934 ve 1937 değişiklikleriyle laiklik, kadın hakları ve Atatürk ilkelerini içine almış; 1961\'e kadar yürürlükte kalmıştır.'),
  ('Hatay\'ın Türkiye\'ye katılmasında Fransa\'nın tutumunu değiştiren uluslararası etken aşağıdakilerden hangisidir?', 'Almanya ve İtalya tehdidi karşısında Türkiye\'nin desteğine ihtiyaç duyması', ['Fransa\'nın Suriye\'den tümüyle vazgeçmesi', 'ABD\'nin Fransa\'ya savaş açması', 'Sovyetler Birliği\'nin Hatay\'ı istemesi ve işgal etmesi'], 'Avrupa\'da savaşın yaklaşması Fransa\'yı Türkiye ile iyi ilişkiler kurmaya yöneltmiş; bu da Hatay sorununun Türkiye lehine çözülmesini kolaylaştırmıştır.'),
  ('Johnson Mektubu\'nun ardından Türkiye\'nin dış politikasında görülen değişim aşağıdakilerden hangisidir?', 'ABD\'ye bağımlılığı azaltıp çok yönlü ilişkiler arama', ['Varşova Paktı\'na katılma kararı alma', 'NATO\'dan çekilerek tarafsızlık ilan etme', 'Kıbrıs üzerindeki haklarından tümüyle vazgeçme'], '1964 Johnson Mektubu Türkiye\'de ABD\'ye güveni sarsmış; Türkiye Sovyetler ve Bağlantısızlar ile ilişkilerini geliştirerek dış politikasını çeşitlendirmiştir.'),
  ('Süveyş Krizi (1956) ile Küba Füze Krizi\'nin (1962) ortak özelliği aşağıdakilerden hangisidir?', 'Süper güçlerin baskısıyla bir tarafın geri adım atması', ['İkisinin de Avrupa\'da yaşanması', 'İkisinde de nükleer silah kullanılması', 'İkisinin de NATO\'nun dağılmasına yol açması'], 'Süveyş\'te İngiltere, Fransa ve İsrail ABD-SSCB baskısıyla çekilmiş; Küba\'da ise Sovyetler ABD\'nin ablukası karşısında füzeleri geri çekmiştir.'),
  ('TBMM\'nin 1920\'de açılmasından 1923\'te Cumhuriyet\'in ilanına kadar uygulanan meclis hükümeti sisteminde ortaya çıkan sorun aşağıdakilerden hangisidir?', 'Bakanların tek tek seçilmesi nedeniyle hükümet kurmanın güçleşmesi', ['Meclisin hiçbir yasama yetkisinin olmaması', 'Padişahın bakanları ataması', 'Yürütmenin yabancı devletlere bırakılması'], 'Bakanların meclisçe tek tek seçilmesi zamanla bunalımlara yol açmış; Ekim 1923\'teki hükümet bunalımı Cumhuriyetin ilanıyla aşılmıştır.'),
];
